class Solution {
  public boolean partitionArray(int[] nums, int k) {
    int n = nums.length;
    if (n % k != 0) return false;
    int groups = n / k;
    int[] freq = new int[100001];
    for (int x : nums) {
      // a value can appear at most once per group
      if (++freq[x] > groups) return false;
    }
    return true;
  }
}
